# Instrucciones en español. Las de ejercicios con imagen de Everkinetic están adaptadas
# y traducidas de everkinetic/data (CC BY-SA 4.0); las de face pull, hip thrust y
# elevación de piernas colgado son propias.
STEPS = {
"bench-press": ["Túmbate en un banco plano con los pies apoyados en el suelo y la espalda pegada al banco.", "Agarra la barra un poco más abierta que el ancho de hombros.", "Saca la barra del soporte y colócala sobre la mitad del pecho con los brazos extendidos: es la posición inicial.", "Baja la barra de forma controlada hasta rozar el pecho.", "Empuja hasta extender los brazos y repite."],
"incline-bench-press": ["Túmbate en un banco inclinado (unos 30–45°) con los pies firmes en el suelo.", "Agarra la barra un poco más abierta que el ancho de hombros.", "Saca la barra y colócala sobre la parte alta del pecho con los brazos extendidos.", "Bájala controlando hasta rozar el pecho, sin rebotar.", "Empuja hacia arriba hasta extender los brazos y repite."],
"decline-bench-press": ["Túmbate en un banco declinado con la cabeza más baja que los pies y las piernas sujetas.", "Agarra la barra algo más abierta que el ancho de hombros.", "Sostén la barra sobre el pecho con los brazos extendidos.", "Bájala lenta y controlada hacia la parte baja del pecho.", "Empuja de vuelta a la posición inicial y repite."],
"dumbbell-bench-press": ["Túmbate en un banco plano con una mancuerna en cada mano y los pies firmes en el suelo.", "Empuja las mancuernas sobre el pecho hasta extender los brazos: posición inicial.", "Baja las mancuernas despacio a los lados del pecho, hasta donde te resulte cómodo.", "Empuja de nuevo hacia arriba de forma controlada y repite."],
"incline-dumbbell-press": ["Ajusta el banco a unos 30–45° y siéntate con una mancuerna en cada mano.", "Empieza con las mancuernas a la altura de los hombros y los codos apuntando hacia abajo.", "Empuja las mancuernas hacia arriba, acercándolas sobre el pecho.", "Bájalas despacio a la posición inicial y repite."],
"machine-chest-press": ["Ajusta el asiento para que las asas queden a la altura del pecho.", "Siéntate con la espalda apoyada y agarra las asas.", "Empuja hacia delante hasta casi extender los brazos, de forma continua.", "Haz una pausa breve y vuelve despacio a la posición inicial."],
"dumbbell-fly": ["Túmbate en un banco plano con una mancuerna en cada mano y los pies en el suelo.", "Sube las mancuernas sobre el pecho con los codos ligeramente flexionados: posición inicial.", "Manteniendo esa flexión, abre los brazos en arco hacia los lados hasta notar estiramiento en el pecho.", "Vuelve por el mismo arco a la posición inicial.", "Mantén la espalda y la cadera apoyadas en el banco todo el tiempo."],
"incline-dumbbell-fly": ["Túmbate en un banco inclinado (30–45°) con una mancuerna en cada mano.", "Sube las mancuernas sobre el pecho con las palmas enfrentadas y los codos un poco flexionados.", "Abre los brazos en arco hacia los lados hasta notar estiramiento en el pecho.", "Vuelve despacio a la posición inicial manteniendo la espalda apoyada."],
"cable-crossover": ["Coloca las poleas a la altura de los hombros o más altas.", "Agarra un asa en cada mano y da un paso al frente con un pie algo adelantado.", "Con los codos ligeramente flexionados, junta las manos delante del pecho en un arco hacia abajo.", "Mantén un instante cuando las manos se encuentren.", "Vuelve de forma lenta y controlada a la posición inicial."],
"pec-deck": ["Ajusta el asiento para que las almohadillas o asas queden a la altura del pecho.", "Siéntate con la espalda apoyada en el respaldo.", "Junta los brazos delante del pecho apretando los pectorales.", "Vuelve despacio a la posición abierta y repite."],
"push-up": ["Apoya las manos en el suelo algo más abiertas que los hombros y estira las piernas sobre las puntas de los pies.", "Mete el abdomen: cabeza, espalda y piernas deben formar una línea recta.", "Baja el cuerpo flexionando los codos hasta acercar el pecho al suelo.", "Empuja hasta extender los brazos sin dejar que la cadera suba o caiga."],
"dips": ["Agárrate a las paralelas y sube hasta quedar con los brazos extendidos.", "Inclina un poco el torso hacia delante.", "Baja flexionando los codos de forma controlada, con el pecho guiando el movimiento.", "Empuja hasta volver arriba sin bloquear del todo los codos."],
"dumbbell-pullover": ["Túmbate en un banco plano con los pies en el suelo y sostén una mancuerna con ambas manos sobre el pecho.", "Con los codos casi rectos, baja la mancuerna en arco por detrás de la cabeza hasta donde no haya dolor.", "Vuelve por el mismo arco a la posición inicial y repite."],
"pull-up": ["Agarra la barra con las palmas hacia delante, algo más abierta que los hombros.", "Cuelga con los brazos extendidos, pecho fuera y abdomen firme.", "Tira llevando los codos hacia abajo y atrás hasta que la barbilla supere la barra.", "Baja despacio hasta extender los brazos por completo."],
"chin-up": ["Agarra la barra con las palmas hacia ti (agarre supino) a la anchura de los hombros.", "Cuelga con los brazos extendidos y el abdomen firme.", "Tira hasta que la barbilla supere la barra.", "Baja de forma controlada a la posición inicial."],
"lat-pulldown": ["Siéntate en la máquina con los muslos bajo los rodillos.", "Agarra la barra ancha con las palmas hacia delante.", "Con la espalda recta y el pecho fuera, tira de la barra hasta la parte alta del pecho.", "Haz una pausa y deja subir la barra despacio hasta estirar los brazos."],
"v-bar-pulldown": ["Coloca el agarre en V en la polea alta y siéntate con los muslos sujetos.", "Agarra las asas con las palmas enfrentadas, espalda recta y abdomen firme.", "Tira del agarre hacia la parte alta del pecho.", "Haz una pausa y vuelve despacio a la posición inicial."],
"straight-arm-pulldown": ["De pie frente a la polea alta, agarra la barra con un agarre ancho.", "Mantén el torso firme y los codos ligeramente flexionados.", "Baja la barra en arco hasta los muslos sin doblar más los codos.", "Vuelve de forma controlada a la posición inicial."],
"barbell-row": ["De pie, con las rodillas algo flexionadas, inclina el torso hacia delante con la espalda recta.", "Agarra la barra con las palmas hacia abajo, algo más abierta que los hombros.", "Tira de la barra hacia la parte baja del pecho o el abdomen, llevando los codos atrás.", "Haz una pausa y baja la barra de forma controlada."],
"reverse-grip-barbell-row": ["Inclínate hacia delante con las rodillas algo flexionadas y la espalda recta.", "Agarra la barra con las palmas hacia arriba (agarre supino).", "Tira de la barra hacia el abdomen con los codos pegados al cuerpo.", "Haz una pausa arriba y baja de forma controlada."],
"one-arm-dumbbell-row": ["Apoya la rodilla y la mano del mismo lado en un banco plano; el otro pie en el suelo.", "Con la espalda recta, coge la mancuerna con la mano libre y el brazo extendido.", "Tira de la mancuerna hacia la cadera llevando el codo atrás.", "Haz una pausa arriba, baja de forma controlada y cambia de lado al terminar."],
"seated-cable-row": ["Siéntate en la polea baja con los pies apoyados y las rodillas algo flexionadas.", "Agarra el asa con la espalda recta y el abdomen firme.", "Tira del asa hacia el abdomen manteniendo el torso erguido y los codos cerca del cuerpo.", "Haz una pausa y vuelve despacio hasta estirar los brazos."],
"t-bar-row": ["Colócate con un pie a cada lado de la barra T y las rodillas algo flexionadas.", "Inclina el torso con la espalda recta y agarra las asas.", "Tira de la barra hacia el pecho con los codos cerca del cuerpo.", "Haz una pausa arriba y baja de forma controlada."],
"deadlift": ["Colócate con los pies al ancho de los hombros y la barra sobre la mitad del pie.", "Flexiona cadera y rodillas y agarra la barra justo por fuera de las piernas, con la espalda recta.", "Empuja el suelo con las piernas y extiende la cadera hasta quedar de pie, con la barra pegada al cuerpo.", "Baja la barra de forma controlada llevando la cadera atrás, sin redondear la espalda.", "Es un ejercicio técnico: aprende el movimiento con poco peso."],
"hyperextension": ["Ajusta el banco para que los tobillos queden bajo los rodillos y la cadera apoyada en el cojín.", "Cruza los brazos sobre el pecho con la espalda recta.", "Baja el torso doblándote por la cadera, sin redondear la espalda.", "Sube hasta que el cuerpo quede en línea recta, sin arquear de más."],
"good-morning": ["Coloca una barra ligera sobre los hombros, detrás del cuello.", "Con las rodillas algo flexionadas y la espalda completamente recta, inclínate llevando la cadera atrás.", "Baja hasta que el torso quede casi paralelo al suelo o hasta notar estiramiento en los isquios.", "Vuelve a la posición erguida y repite."],
"overhead-press": ["Siéntate en un banco con respaldo, espalda recta y abdomen firme.", "Agarra la barra a la anchura de los hombros y colócala delante, a la altura de la clavícula.", "Empuja la barra hacia arriba hasta casi extender los brazos.", "Haz una pausa arriba y bájala controlando hasta la posición inicial."],
"dumbbell-shoulder-press": ["Siéntate en un banco con respaldo y una mancuerna en cada mano.", "Empieza con las mancuernas a la altura de los hombros y las palmas hacia delante.", "Empuja hacia arriba hasta casi extender los brazos, acercando las mancuernas.", "Baja de forma controlada a la posición inicial."],
"arnold-press": ["Siéntate con la espalda apoyada y una mancuerna en cada mano.", "Empieza con las mancuernas delante de los hombros y las palmas mirando hacia ti.", "Empuja hacia arriba girando las muñecas hasta que las palmas miren hacia delante.", "Baja deshaciendo el giro hasta la posición inicial. Empieza con poco peso."],
"machine-shoulder-press": ["Ajusta el asiento para que las asas queden a la altura de los hombros.", "Siéntate con la espalda apoyada y el abdomen firme.", "Empuja las asas hacia arriba hasta casi extender los brazos.", "Haz una pausa y baja de forma controlada."],
"lateral-raise": ["De pie, con una mancuerna en cada mano a los lados del cuerpo y las rodillas algo flexionadas.", "Con los codos ligeramente flexionados, eleva los brazos hacia los lados.", "Sube hasta la altura de los hombros, sin balancear el torso.", "Mantén un instante y baja despacio."],
"front-raise": ["De pie, con una mancuerna en cada mano delante de los muslos.", "Con el brazo casi recto, eleva una mancuerna al frente hasta la altura del hombro.", "Baja de forma controlada y repite con el otro brazo."],
"rear-delt-fly": ["Apoya la frente o el pecho en un banco inclinado de forma que el torso quede inclinado hacia delante.", "Deja colgar las mancuernas con los codos ligeramente flexionados.", "Abre los brazos hacia los lados hasta la altura de los hombros.", "Haz una pausa y baja despacio."],
"upright-row": ["De pie, con la barra delante de los muslos y las manos a la anchura de los hombros.", "Tira de la barra hacia arriba pegada al cuerpo, llevando los codos hacia fuera y arriba.", "Sube hasta la parte alta del pecho, sin pasar de la altura de los hombros con los codos.", "Baja de forma controlada. Si te molesta el hombro, usa un agarre más abierto o cambia de ejercicio."],
"barbell-shrug": ["De pie, con la espalda recta, sostén la barra con los brazos extendidos.", "Deja caer los hombros todo lo posible.", "Eleva los hombros hacia las orejas lo más alto que puedas, sin doblar los codos.", "Haz una pausa y baja de forma controlada."],
"dumbbell-shrug": ["De pie, con una mancuerna en cada mano a los lados del cuerpo.", "Deja caer los hombros todo lo posible.", "Eleva los hombros hacia las orejas con los brazos rectos.", "Mantén un instante y baja de forma controlada."],
"barbell-curl": ["De pie, con las rodillas algo flexionadas, agarra la barra con las palmas hacia arriba a la anchura de los hombros.", "Con los codos fijos a los lados del cuerpo, sube la barra flexionando solo los codos.", "Haz una pausa arriba y baja despacio hasta extender los brazos.", "No balancees la cadera ni la espalda."],
"ez-bar-curl": ["De pie, agarra la barra Z por la parte angulada con las palmas hacia arriba.", "Con los codos fijos a los lados, sube la barra hacia el pecho.", "Baja despacio hasta extender los brazos. Evita balancear el cuerpo."],
"dumbbell-curl": ["De pie, con una mancuerna en cada mano y las palmas hacia delante.", "Con los codos fijos a los lados, sube las mancuernas flexionando los codos.", "Baja despacio hasta extender los brazos.", "No balancees el cuerpo."],
"hammer-curl": ["De pie, con una mancuerna en cada mano y las palmas mirando hacia el cuerpo.", "Con los codos fijos, sube las mancuernas hacia los hombros sin girar las muñecas.", "Baja de forma controlada y repite."],
"incline-dumbbell-curl": ["Ajusta el banco a unos 45° y siéntate con una mancuerna en cada mano.", "Deja colgar los brazos estirados a los lados.", "Con el codo fijo, sube la mancuerna flexionando el codo.", "Baja despacio hasta estirar el brazo; puedes alternar brazos."],
"preacher-curl": ["Ajusta el asiento para que las axilas queden sobre el borde del banco Scott.", "Agarra la barra con las palmas hacia arriba y apoya los brazos en el cojín.", "Sube la barra hacia los hombros sin despegar los brazos del cojín.", "Baja despacio hasta casi extender los codos."],
"concentration-curl": ["Siéntate en el extremo de un banco con las piernas separadas.", "Coge una mancuerna y apoya el codo en la cara interna del muslo.", "Sube la mancuerna hacia el hombro moviendo solo el antebrazo.", "Baja despacio y cambia de brazo al terminar."],
"cable-curl": ["Coloca una barra corta en la polea baja y ponte de pie frente a ella.", "Agarra la barra con las palmas hacia arriba.", "Con los codos fijos a los lados, sube la barra hacia el pecho.", "Haz una pausa y baja despacio. No balancees el cuerpo."],
"triceps-pushdown": ["Coloca una barra corta en la polea alta y agárrala con las palmas hacia abajo.", "Con los codos pegados al cuerpo, espalda recta y abdomen firme, empuja la barra hacia los muslos.", "Extiende los codos por completo y haz una pausa.", "Vuelve despacio sin despegar los codos."],
"rope-pushdown": ["Coloca una cuerda en la polea alta y agárrala con las palmas enfrentadas.", "Con los codos pegados al cuerpo, empuja la cuerda hacia abajo.", "Al final, separa los extremos de la cuerda hacia fuera.", "Vuelve despacio sin despegar los codos."],
"overhead-triceps-extension": ["De pie o sentado, sostén una mancuerna con ambas manos por encima de la cabeza.", "Con los codos cerca de la cabeza, baja la mancuerna por detrás de la nuca.", "Extiende los codos para volver arriba.", "Mueve solo los antebrazos; los codos no se abren."],
"skull-crusher": ["Túmbate en un banco plano con una barra (o barra Z) sobre el pecho y agarre cerrado.", "Extiende los brazos con la barra sobre los hombros.", "Flexionando solo los codos, baja la barra hacia la frente.", "Extiende los codos para volver a la posición inicial."],
"close-grip-bench-press": ["Túmbate en un banco plano con los pies en el suelo.", "Agarra la barra con las manos algo más juntas que el ancho de hombros.", "Baja la barra a la parte baja del pecho con los codos cerca del cuerpo.", "Empuja hasta extender los brazos y repite."],
"triceps-kickback": ["Apoya rodilla y mano del mismo lado en un banco, con la espalda recta.", "Con la mancuerna en la otra mano, sube el codo hasta la altura del torso y fíjalo.", "Extiende el codo llevando la mancuerna hacia atrás.", "Vuelve despacio sin mover el brazo y cambia de lado al terminar."],
"bench-dips": ["Siéntate en el borde de un banco y apoya las manos a los lados de la cadera.", "Coloca los pies en el suelo o en otro banco, con las piernas estiradas.", "Baja el cuerpo flexionando los codos hasta unos 90°.", "Empuja hasta extender los brazos. No bajes de más si te molestan los hombros."],
"back-squat": ["Coloca la barra sobre la parte alta de la espalda, no sobre el cuello.", "Separa los pies algo más que el ancho de hombros, con las puntas un poco hacia fuera.", "Con el abdomen firme, baja flexionando cadera y rodillas como si te sentaras.", "Baja hasta donde controles con la espalda recta y las rodillas en la dirección de los pies.", "Sube empujando el suelo hasta quedar de pie."],
"front-squat": ["Apoya la barra sobre la parte delantera de los hombros, con los codos altos.", "Separa los pies al ancho de hombros con las puntas algo hacia fuera.", "Baja como si te sentaras, manteniendo el torso erguido.", "Sube empujando el suelo hasta quedar de pie."],
"smith-squat": ["Coloca la barra de la máquina Smith a la altura de los hombros y sitúate debajo.", "Separa los pies algo más que el ancho de hombros, un poco adelantados.", "Desbloquea la barra y baja flexionando cadera y rodillas.", "Sube empujando el suelo y bloquea la barra al terminar."],
"hack-squat": ["Colócate en la máquina con la espalda y los hombros contra los cojines.", "Pon los pies en la plataforma, al ancho de los hombros.", "Libera los seguros y baja flexionando las rodillas de forma controlada.", "Empuja la plataforma hasta casi extender las piernas."],
"leg-press": ["Siéntate en la máquina con la espalda apoyada y los pies en la plataforma, al ancho de los hombros.", "Empuja la plataforma y quita los seguros.", "Baja despacio flexionando las rodillas en la dirección de los pies.", "Empuja hasta casi extender las piernas, sin bloquear las rodillas ni rebotar."],
"leg-extension": ["Ajusta el asiento para que la rodilla quede alineada con el eje de la máquina y el rodillo justo encima de los tobillos.", "Agarra las asas y mantén la espalda apoyada.", "Extiende las piernas hasta casi estirar las rodillas.", "Baja de forma controlada, sin dejar caer el peso."],
"bulgarian-split-squat": ["De espaldas a un banco, apoya el empeine de un pie sobre él y adelanta el otro pie.", "Con la barra en la espalda (o mancuernas en las manos), mantén el torso erguido.", "Baja flexionando la rodilla delantera hasta que el muslo quede casi paralelo al suelo.", "Sube empujando con la pierna delantera y cambia de pierna al terminar."],
"dumbbell-lunge": ["De pie, con una mancuerna en cada mano y los pies algo separados.", "Da un paso largo al frente con el torso erguido.", "Baja hasta que la rodilla trasera quede cerca del suelo, sin tocarlo.", "Empuja con la pierna delantera para volver y alterna las piernas."],
"walking-lunge": ["De pie, con mancuernas en las manos o una barra en la espalda.", "Da un paso largo al frente y baja hasta que la rodilla trasera quede cerca del suelo.", "Empuja con el pie de atrás y avanza dando el siguiente paso con la otra pierna.", "Practica primero sin peso hasta dominar el movimiento."],
"step-up": ["Coloca un banco o cajón estable delante de ti y coge una mancuerna en cada mano.", "Sube un pie al banco y empuja con esa pierna hasta quedar de pie encima.", "Baja de forma controlada.", "Repite con la otra pierna."],
"romanian-deadlift": ["De pie, sostén la barra delante de los muslos con un agarre algo más abierto que los hombros.", "Con las rodillas ligeramente flexionadas, lleva la cadera hacia atrás y baja la barra pegada a las piernas.", "Baja hasta notar estiramiento en los isquios, con la espalda recta.", "Extiende la cadera para volver a quedar de pie."],
"lying-leg-curl": ["Túmbate boca abajo en la máquina con los talones bajo el rodillo.", "Agarra las asas para estabilizarte.", "Flexiona las rodillas llevando los talones hacia los glúteos.", "Haz una pausa y baja de forma controlada."],
"seated-leg-curl": ["Ajusta la máquina para que el rodillo quede justo encima de los talones.", "Siéntate erguido con la espalda apoyada y las piernas estiradas.", "Flexiona las rodillas llevando el rodillo hacia abajo y atrás.", "Haz una pausa y vuelve despacio."],
"hip-thrust": ["Siéntate en el suelo con la parte alta de la espalda apoyada en el borde de un banco.", "Coloca la barra sobre la cadera (con una almohadilla) y los pies en el suelo, al ancho de la cadera.", "Empuja con los talones y eleva la cadera hasta que el torso quede paralelo al suelo.", "Aprieta los glúteos arriba un instante y baja de forma controlada."],
"glute-bridge": ["Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.", "Con el abdomen firme, eleva la cadera apretando los glúteos.", "Sube hasta que hombros, cadera y rodillas queden en línea.", "Baja despacio y repite."],
"cable-kickback": ["Coloca una tobillera en la polea baja y sujétala a un tobillo.", "De pie frente a la máquina, agárrate y flexiona un poco la rodilla de apoyo.", "Lleva la pierna hacia atrás en arco, apretando el glúteo.", "Vuelve despacio y cambia de pierna al terminar."],
"hip-abduction": ["Siéntate en la máquina con la parte externa de las rodillas contra los cojines.", "Con la espalda apoyada, separa las piernas contra la resistencia.", "Vuelve despacio a la posición inicial."],
"hip-adduction": ["Siéntate en la máquina con la parte interna de las rodillas contra los cojines.", "Con la espalda apoyada, junta las piernas contra la resistencia.", "Vuelve despacio a la posición inicial."],
"standing-calf-raise": ["Colócate en la máquina con los hombros bajo los cojines y las puntas de los pies en el escalón.", "Deja bajar los talones para estirar los gemelos.", "Sube sobre las puntas de los pies todo lo que puedas.", "Mantén un instante y baja de forma controlada."],
"seated-calf-raise": ["Siéntate en la máquina con las puntas de los pies en la plataforma.", "Coloca los muslos bajo el cojín, justo por encima de las rodillas.", "Libera el seguro y sube los talones todo lo que puedas.", "Haz una pausa y baja despacio hasta estirar."],
"crunch": ["Túmbate boca arriba con las rodillas flexionadas (o los pies sobre un banco).", "Coloca las manos sobre el pecho o a los lados de la cabeza, sin tirar del cuello.", "Eleva la cabeza y los hombros del suelo contrayendo el abdomen.", "Mantén un instante y baja de forma controlada, con la zona lumbar apoyada."],
"cable-crunch": ["Coloca una cuerda en la polea alta y arrodíllate frente a ella.", "Sujeta la cuerda a los lados de la cabeza.", "Flexiona el tronco llevando los codos hacia las rodillas, sin mover la cadera.", "Vuelve despacio a la posición inicial."],
"decline-crunch": ["Túmbate boca arriba en un banco declinado con los pies sujetos bajo los rodillos.", "Coloca las manos sobre el pecho o a los lados de la cabeza.", "Eleva el tronco contrayendo el abdomen.", "Haz una pausa y baja de forma controlada."],
"lying-leg-raise": ["Túmbate boca arriba en un banco o en el suelo con las manos bajo la cadera.", "Con las piernas casi rectas, elévalas hasta formar unos 90° con el tronco.", "Baja despacio sin que la zona lumbar se despegue."],
"hanging-leg-raise": ["Cuélgate de una barra con los brazos extendidos y las piernas juntas.", "Sin balancearte, eleva las piernas (rectas o con las rodillas flexionadas) hacia el pecho.", "Sube hasta que los muslos queden al menos paralelos al suelo, inclinando la pelvis hacia arriba.", "Baja de forma controlada."],
"ab-rollout": ["Arrodíllate y agarra una barra con discos (o una rueda abdominal) delante de ti.", "Con los brazos rectos y el abdomen firme, rueda hacia delante estirando el cuerpo.", "Llega hasta donde controles sin que se hunda la zona lumbar.", "Vuelve rodando hacia las rodillas contrayendo el abdomen."],
"side-plank": ["Túmbate de lado apoyado en el antebrazo, con el codo bajo el hombro y las piernas estiradas.", "Con el abdomen firme, eleva la cadera hasta que el cuerpo quede en línea recta.", "Mantén la posición el tiempo indicado.", "Baja y repite del otro lado."],
"dumbbell-side-bend": ["De pie, con una mancuerna en una mano y la otra en la cintura.", "Inclina el tronco hacia el lado de la mancuerna, sin girar.", "Vuelve a la posición erguida usando el oblicuo contrario.", "Cambia de lado al terminar."],
"face-pull": ["Coloca una cuerda en la polea a la altura de la cara o algo más alta.", "Agarra los extremos de la cuerda y da un paso atrás con los brazos estirados.", "Tira de la cuerda hacia la cara separando las manos y llevando los codos hacia fuera y atrás.", "Aprieta la parte posterior de los hombros un instante y vuelve despacio."],
}
